{
  "root_causes": [
    {
      "service": "ts-travel-plan-service",
      "fault_kind": "http_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name AS caller, p.service_name AS callee, c.span_name, COUNT(*) AS n, ROUND(approx_quantile(c.duration/1e6,0.5),1) AS caller_p50_ms, ROUND(approx_quantile(p.duration/1e6,0.5),1) AS callee_server_p50_ms FROM abnormal_traces c JOIN abnormal_traces p ON p.parent_span_id=c.span_id AND p.trace_id=c.trace_id AND p.attr_span_kind='Server' WHERE c.service_name='ts-travel-plan-service' AND c.attr_span_kind='Client' AND p.service_name='ts-seat-service' GROUP BY 1,2,3",
          "claim": "Travel-plan's POST to seat left_tickets takes about 2.3 s at the caller while seat's server span is about 17 ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT c.service_name AS caller, p.service_name AS callee, c.span_name, COUNT(*) AS n, ROUND(approx_quantile(c.duration/1e6,0.5),1) AS caller_p50_ms, ROUND(approx_quantile(p.duration/1e6,0.5),1) AS callee_server_p50_ms FROM normal_traces c JOIN normal_traces p ON p.parent_span_id=c.span_id AND p.trace_id=c.trace_id AND p.attr_span_kind='Server' WHERE c.service_name='ts-travel-plan-service' AND c.attr_span_kind='Client' AND p.service_name='ts-seat-service' GROUP BY 1,2,3",
          "claim": "In the normal period the same travel-plan to seat call takes about 18 ms at the caller."
        },
        {
          "kind": "metric",
          "sql": "SELECT 'abn' AS p, metric, attr_source, attr_destination, service_name, ROUND(SUM(sum)/NULLIF(SUM(count),0),4) AS mean_s FROM abnormal_metrics_histogram WHERE metric='hubble_http_request_duration_seconds' AND service_name IN ('ts-travel-plan-service','ts-seat-service') AND attr_destination LIKE '%seat%' AND attr_source LIKE '%travel-plan%' GROUP BY 1,2,3,4,5",
          "claim": "Hubble HTTP duration on the travel-plan to seat connection stays about 30 ms, so the wire is not slow."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, COUNT(*) AS n, ROUND(approx_quantile(duration/1e6,0.5),1) AS p50_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' AND span_name LIKE 'POST /api/v1/travelplanservice%' GROUP BY 1,2",
          "claim": "User-facing travelPlan requests at ui-dashboard take 12-19 s at p50 in the abnormal period."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, COUNT(*) AS n, ROUND(approx_quantile(duration/1e6,0.5),1) AS p50_ms FROM abnormal_traces WHERE service_name='ts-travel-plan-service' AND attr_span_kind='Server' AND span_name LIKE 'POST /api/v1/travelplanservice%' GROUP BY 1,2",
          "claim": "Travel-plan's server spans for quickest, cheapest and minStation take 10-19 s at p50, and ui-dashboard's calls to them inherit this."
        }
      ]
    }
  ]
}
